create table public.vault_governed_inventory_cost_lots(id uuid primary key default gen_random_uuid(),purchase_order_id uuid not null references public.vault_purchase_orders(id),purchase_order_line_id uuid not null references public.vault_purchase_order_lines(id),purchase_order_line_size_allocation_id uuid not null references public.vault_purchase_order_line_size_allocations(id),receipt_id uuid not null references public.vault_purchase_order_receipts(id),receipt_line_id uuid not null references public.vault_purchase_order_receipt_lines(id),receipt_allocation_id uuid not null references public.vault_purchase_order_receipt_allocations(id),receipt_cost_disposition_id uuid not null references public.vault_purchase_order_receipt_cost_dispositions(id),inventory_posting_id uuid not null references public.vault_purchase_order_inventory_postings(id),inventory_posting_line_id uuid not null references public.vault_purchase_order_inventory_posting_lines(id),inventory_posting_success_event_id uuid not null references public.vault_purchase_order_inventory_posting_events(id),variant_id uuid not null references public.vault_variants(id),shopify_variant_id_snapshot text not null,shopify_inventory_item_id_snapshot text not null,shopify_location_id_snapshot text not null,admission_start_unit integer not null check(admission_start_unit>=0),admission_end_unit integer not null check(admission_end_unit>admission_start_unit),admitted_quantity integer not null check(admitted_quantity=admission_end_unit-admission_start_unit),admitted_gbp_minor_units bigint not null check(admitted_gbp_minor_units>=0),allocation_method text not null default 'sellable_disposition_cumulative_floor',allocation_method_version text not null default 'v1',provenance_key text not null unique,created_at timestamptz not null default now(),unique(receipt_cost_disposition_id,admission_start_unit,admission_end_unit,allocation_method,allocation_method_version));
alter table public.vault_governed_inventory_cost_lots enable row level security;create trigger vault_governed_inventory_cost_lots_immutable before update or delete on public.vault_governed_inventory_cost_lots for each row execute function public.reject_purchase_cost_evidence_mutation();revoke all on public.vault_governed_inventory_cost_lots from public,anon,authenticated,service_role;grant select,insert on public.vault_governed_inventory_cost_lots to service_role;create policy vault_governed_inventory_cost_lots_service_select on public.vault_governed_inventory_cost_lots for select to service_role using(true);create policy vault_governed_inventory_cost_lots_service_insert on public.vault_governed_inventory_cost_lots for insert to service_role with check(true);
create function public.derive_governed_inventory_cost_lots(target_purchase_order_id uuid,target_operator_id uuid,target_idempotency_key text) returns integer language plpgsql security invoker set search_path='' as $$declare d record; eligible int; admitted int; admitted_gbp bigint; event_id uuid; posting_id uuid; posting_line_id uuid; amount bigint; n int; result int:=0;begin
if target_idempotency_key is null or nullif(trim(target_idempotency_key),'') is null then raise exception 'INVENTORY_COST_LOT_IDEMPOTENCY_REQUIRED';end if;if not exists(select 1 from public.vault_operators o where o.id=target_operator_id and o.is_active) then raise exception 'ACTIVE_OPERATOR_REQUIRED';end if;
for d in select x.*,rr.id receipt_id,rl.id receipt_line_id,ra.variant_id,ra.shopify_variant_id_snapshot rv,ra.shopify_inventory_item_id_snapshot ri,sa.variant_id sv,sa.shopify_variant_id_snapshot ssv,sa.shopify_inventory_item_id_snapshot ssi,rr.shopify_location_id_snapshot location_snapshot from public.vault_purchase_order_receipt_cost_dispositions x join public.vault_purchase_order_receipt_allocations ra on ra.id=x.receipt_allocation_id join public.vault_purchase_order_receipt_lines rl on rl.id=ra.receipt_line_id and rl.purchase_order_line_id=x.purchase_order_line_id join public.vault_purchase_order_receipts rr on rr.id=rl.receipt_id and rr.id=x.receipt_id and rr.purchase_order_id=x.purchase_order_id join public.vault_purchase_order_line_size_allocations sa on sa.id=ra.purchase_order_line_size_allocation_id and sa.id=x.purchase_order_line_size_allocation_id and sa.purchase_order_line_id=x.purchase_order_line_id where x.purchase_order_id=target_purchase_order_id and x.disposition_type='sellable_inventory' loop
perform pg_advisory_xact_lock(hashtextextended(d.id::text,74000));if d.variant_id<>d.sv or d.rv<>d.ssv or d.ri<>d.ssi or not exists(select 1 from public.vault_variants v where v.id=d.variant_id and v.source='shopify' and v.source_active and v.source_variant_id=d.rv and v.source_inventory_item_id=d.ri) or not exists(select 1 from public.vault_locations l where l.id=(select received_location_id from public.vault_purchase_order_receipts where id=d.receipt_id) and l.source='shopify' and l.active and l.source_location_id=d.location_snapshot) then raise exception 'INVENTORY_COST_LOT_IDENTITY_INVALID';end if;
select coalesce(sum(q.quantity),0)::int,(array_agg(q.event_id order by q.posting_line_id))[1],(array_agg(q.posting_id order by q.posting_line_id))[1],(array_agg(q.posting_line_id order by q.posting_line_id))[1] into eligible,event_id,posting_id,posting_line_id from(select distinct pl.id posting_line_id,pl.posting_id,pl.quantity,e.id event_id from public.vault_purchase_order_inventory_posting_lines pl join public.vault_purchase_order_inventory_postings p on p.id=pl.posting_id and p.receipt_id=d.receipt_id and p.shopify_location_id_snapshot=d.location_snapshot join public.vault_purchase_order_inventory_posting_events e on e.posting_id=p.id and e.event_type='shopify_succeeded' where pl.receipt_allocation_id=d.receipt_allocation_id and pl.shopify_variant_id_snapshot=d.rv and pl.shopify_inventory_item_id_snapshot=d.ri) q;
select coalesce(sum(admitted_quantity),0)::int,coalesce(sum(admitted_gbp_minor_units),0) into admitted,admitted_gbp from public.vault_governed_inventory_cost_lots where receipt_cost_disposition_id=d.id;if eligible>d.quantity or admitted>eligible or admitted>d.quantity or admitted_gbp>d.allocated_gbp_minor_units then raise exception 'INVENTORY_COST_LOT_CONSERVATION_INVALID';end if;if eligible>admitted then amount:=((eligible*d.allocated_gbp_minor_units/d.quantity)-(admitted*d.allocated_gbp_minor_units/d.quantity));insert into public.vault_governed_inventory_cost_lots(purchase_order_id,purchase_order_line_id,purchase_order_line_size_allocation_id,receipt_id,receipt_line_id,receipt_allocation_id,receipt_cost_disposition_id,inventory_posting_id,inventory_posting_line_id,inventory_posting_success_event_id,variant_id,shopify_variant_id_snapshot,shopify_inventory_item_id_snapshot,shopify_location_id_snapshot,admission_start_unit,admission_end_unit,admitted_quantity,admitted_gbp_minor_units,provenance_key) values(d.purchase_order_id,d.purchase_order_line_id,d.purchase_order_line_size_allocation_id,d.receipt_id,d.receipt_line_id,d.receipt_allocation_id,d.id,posting_id,posting_line_id,event_id,d.variant_id,d.rv,d.ri,d.location_snapshot,admitted,eligible,eligible-admitted,amount,'sellable_disposition_cumulative_floor:v1:'||d.id||':'||admitted||':'||eligible) on conflict do nothing;get diagnostics n=row_count;result:=result+n;end if;end loop;return result;end$$;
revoke all on function public.derive_governed_inventory_cost_lots(uuid,uuid,text) from public,anon,authenticated;grant execute on function public.derive_governed_inventory_cost_lots(uuid,uuid,text) to service_role;
create or replace function public.derive_governed_inventory_cost_lots(target_purchase_order_id uuid,target_operator_id uuid,target_idempotency_key text) returns integer language plpgsql security invoker set search_path='' as $$declare d record;eligible int;admitted int;admitted_gbp bigint;event_id uuid;posting_id uuid;posting_line_id uuid;amount bigint;n int;result int:=0;begin if target_idempotency_key is null or nullif(trim(target_idempotency_key),'') is null then raise exception 'INVENTORY_COST_LOT_IDEMPOTENCY_REQUIRED';end if;if not exists(select 1 from public.vault_operators o where o.id=target_operator_id and o.is_active) then raise exception 'ACTIVE_OPERATOR_REQUIRED';end if;for d in select x.*,rr.id receipt_id,rl.id receipt_line_id,ra.variant_id,ra.shopify_variant_id_snapshot rv,ra.shopify_inventory_item_id_snapshot ri,sa.variant_id sv,sa.shopify_variant_id_snapshot ssv,sa.shopify_inventory_item_id_snapshot ssi,rr.shopify_location_id_snapshot location_snapshot from public.vault_purchase_order_receipt_cost_dispositions x join public.vault_purchase_order_receipt_allocations ra on ra.id=x.receipt_allocation_id join public.vault_purchase_order_receipt_lines rl on rl.id=ra.receipt_line_id and rl.purchase_order_line_id=x.purchase_order_line_id join public.vault_purchase_order_receipts rr on rr.id=rl.receipt_id and rr.id=x.receipt_id and rr.purchase_order_id=x.purchase_order_id join public.vault_purchase_order_line_size_allocations sa on sa.id=ra.purchase_order_line_size_allocation_id and sa.id=x.purchase_order_line_size_allocation_id and sa.purchase_order_line_id=x.purchase_order_line_id where x.purchase_order_id=target_purchase_order_id and x.disposition_type='sellable_inventory' loop perform pg_advisory_xact_lock(hashtextextended(d.id::text,74000));if d.variant_id<>d.sv or d.rv<>d.ssv or d.ri<>d.ssi or not exists(select 1 from public.vault_variants v where v.id=d.variant_id and v.source='shopify' and v.source_active and v.source_variant_id=d.rv and v.source_inventory_item_id=d.ri) or not exists(select 1 from public.vault_locations l where l.id=(select received_location_id from public.vault_purchase_order_receipts where id=d.receipt_id) and l.source='shopify' and l.active and l.source_location_id=d.location_snapshot) then raise exception 'INVENTORY_COST_LOT_IDENTITY_INVALID';end if;select coalesce(sum(q.quantity),0)::int,(array_agg(q.event_id order by q.posting_line_id))[1],(array_agg(q.posting_id order by q.posting_line_id))[1],(array_agg(q.posting_line_id order by q.posting_line_id))[1] into eligible,event_id,posting_id,posting_line_id from(select pl.id posting_line_id,pl.posting_id,pl.quantity,(select min(e.id) from public.vault_purchase_order_inventory_posting_events e where e.posting_id=p.id and e.event_type='shopify_succeeded') event_id from public.vault_purchase_order_inventory_posting_lines pl join public.vault_purchase_order_inventory_postings p on p.id=pl.posting_id and p.receipt_id=d.receipt_id and p.shopify_location_id_snapshot=d.location_snapshot where pl.receipt_allocation_id=d.receipt_allocation_id and pl.shopify_variant_id_snapshot=d.rv and pl.shopify_inventory_item_id_snapshot=d.ri and exists(select 1 from public.vault_purchase_order_inventory_posting_events e where e.posting_id=p.id and e.event_type='shopify_succeeded')) q;select coalesce(sum(admitted_quantity),0)::int,coalesce(sum(admitted_gbp_minor_units),0) into admitted,admitted_gbp from public.vault_governed_inventory_cost_lots where receipt_cost_disposition_id=d.id;if eligible>d.quantity or admitted>eligible or admitted>d.quantity or admitted_gbp>d.allocated_gbp_minor_units then raise exception 'INVENTORY_COST_LOT_CONSERVATION_INVALID';end if;if eligible>admitted then amount:=((eligible*d.allocated_gbp_minor_units/d.quantity)-(admitted*d.allocated_gbp_minor_units/d.quantity));insert into public.vault_governed_inventory_cost_lots(purchase_order_id,purchase_order_line_id,purchase_order_line_size_allocation_id,receipt_id,receipt_line_id,receipt_allocation_id,receipt_cost_disposition_id,inventory_posting_id,inventory_posting_line_id,inventory_posting_success_event_id,variant_id,shopify_variant_id_snapshot,shopify_inventory_item_id_snapshot,shopify_location_id_snapshot,admission_start_unit,admission_end_unit,admitted_quantity,admitted_gbp_minor_units,provenance_key) values(d.purchase_order_id,d.purchase_order_line_id,d.purchase_order_line_size_allocation_id,d.receipt_id,d.receipt_line_id,d.receipt_allocation_id,d.id,posting_id,posting_line_id,event_id,d.variant_id,d.rv,d.ri,d.location_snapshot,admitted,eligible,eligible-admitted,amount,'sellable_disposition_cumulative_floor:v1:'||d.id||':'||admitted||':'||eligible) on conflict do nothing;get diagnostics n=row_count;result:=result+n;end if;end loop;return result;end$$;
