ntory_item_id=d.ri) or not exists(select 1 from public.vault_locations l where l.id=(select received_location_id from public.vault_purchase_order_receipts where id=d.receipt_id) and l.source='shopify' and l.active and l.source_location_id=d.location_snapshot) then raise exception 'INVENTORY_COST_LOT_IDENTITY_INVALID';end if;select coalesce(sum(q.quantity),0)::int,(array_agg(q.event_id order by q.posting_line_id))[1],(array_agg(q.posting_id order by q.posting_line_id))[1],(array_agg(q.posting_line_id order by q.posting_line_id))[1] into eligible,event_id,posting_id,posting_line_id from(select pl.id posting_line_id,pl.posting_id,pl.quantity,(select e.id from public.vault_purchase_order_inventory_posting_events e where e.posting_id=p.id and e.event_type='shopify_succeeded' order by e.id limit 1) event_id from public.vault_purchase_order_inventory_posting_lines pl join public.vault_purchase_order_inventory_postings p on p.id=pl.posting_id and p.receipt_id=d.receipt_id and p.shopify_location_id_snapshot=d.location_snapshot where pl.receipt_allocation_id=d.receipt_allocation_id and pl.shopify_variant_id_snapshot=d.rv and pl.shopify_inventory_item_id_snapshot=d.ri and exists(select 1 from public.vault_purchase_order_inventory_posting_events e where e.posting_id=p.id and e.event_type='shopify_succeeded')) q;select coalesce(sum(admitted_quantity),0)::int,coalesce(sum(admitted_gbp_minor_units),0) into admitted,admitted_gbp from public.vault_governed_inventory_cost_lots where receipt_cost_disposition_id=d.id;if eligible>d.quantity or admitted>eligible or admitted>d.quantity or admitted_gbp>d.allocated_gbp_minor_units then raise exception 'INVENTORY_COST_LOT_CONSERVATION_INVALID';end if;if eligible>admitted then amount:=((eligible*d.allocated_gbp_minor_units/d.quantity)-(admitted*d.allocated_gbp_minor_units/d.quantity));insert into public.vault_governed_inventory_cost_lots(purchase_order_id,purchase_order_line_id,purchase_order_line_size_allocation_id,receipt_id,receipt_line_id,receipt_allocation_id,receipt_cost_disposition_id,inventory_posting_id,inventory_posting_line_id,inventory_posting_success_event_id,variant_id,shopify_variant_id_snapshot,shopify_inventory_item_id_snapshot,shopify_location_id_snapshot,admission_start_unit,admission_end_unit,admitted_quantity,admitted_gbp_minor_units,provenance_key) values(d.purchase_order_id,d.purchase_order_line_id,d.purchase_order_line_size_allocation_id,d.receipt_id,d.receipt_line_id,d.receipt_allocation_id,d.id,posting_id,posting_line_id,event_id,d.variant_id,d.rv,d.ri,d.location_snapshot,admitted,eligible,eligible-admitted,amount,'sellable_disposition_cumulative_floor:v1:'||d.id||':'||admitted||':'||eligible) on conflict do nothing;get diagnostics n=row_count;result:=result+n;end if;end loop;return result;end$$;
create or replace view public.vault_governed_inventory_cost_state with (security_invoker = true) as
with authoritative_sources as (
select d.id as source_disposition_id,d.purchase_order_id,d.purchase_order_line_id,d.purchase_order_line_size_allocation_id as size_allocation_id,d.receipt_id,d.receipt_allocation_id,d.quantity as source_sellable_quantity,d.allocated_gbp_minor_units as source_sellable_gbp_minor_units,ra.id as linked_receipt_allocation_id,ra.receipt_line_id as linked_receipt_line_id,ra.purchase_order_line_size_allocation_id as linked_size_allocation_id,ra.variant_id as receipt_variant_id,ra.shopify_variant_id_snapshot as shopify_variant_id,ra.shopify_inventory_item_id_snapshot as shopify_inventory_item_id,rl.purchase_order_line_id as receipt_line_purchase_order_line_id,rr.purchase_order_id as receipt_purchase_order_id,rr.shopify_location_id_snapshot as shopify_location_id,sa.variant_id as saved_size_variant_id,sa.shopify_variant_id_snapshot as saved_size_shopify_variant_id,sa.shopify_inventory_item_id_snapshot as saved_size_shopify_inventory_item_id from public.vault_purchase_order_receipt_cost_dispositions d left join public.vault_purchase_order_receipt_allocations ra on ra.id=d.receipt_allocation_id left join public.vault_purchase_order_receipt_lines rl on rl.id=ra.receipt_line_id left join public.vault_purchase_order_receipts rr on rr.id=d.receipt_id left join public.vault_purchase_order_line_size_allocations sa on sa.id=d.purchase_order_line_size_allocation_id where d.disposition_type='sellable_inventory'
),source_identity as (
select s.*,(s.linked_receipt_allocation_id is not null and s.linked_size_allocation_id=s.size_allocation_id and s.linked_receipt_line_id is not null and s.receipt_line_purchase_order_line_id=s.purchase_order_line_id and s.receipt_purchase_order_id=s.purchase_order_id and s.saved_size_variant_id=s.receipt_variant_id and s.saved_size_shopify_variant_id=s.shopify_variant_id and s.saved_size_shopify_inventory_item_id=s.shopify_inventory_item_id) as internal_linkage_consistent from authoritative_sources s
),identity_classification as (
select s.source_disposition_id,(s.internal_linkage_consistent and not exists(select 1 from public.vault_purchase_order_inventory_posting_lines pl join public.vault_purchase_order_inventory_postings p on p.id=pl.posting_id where pl.receipt_allocation_id=s.receipt_allocation_id and exists(select 1 from public.vault_purchase_order_inventory_posting_events e where e.posting_id=p.id and e.event_type='shopify_succeeded') and (p.receipt_id<>s.receipt_id or p.shopify_location_id_snapshot<>s.shopify_location_id or pl.shopify_variant_id_snapshot<>s.shopify_variant_id or pl.shopify_inventory_item_id_snapshot<>s.shopify_inventory_item_id))) as identity_consistent from source_identity s
),eligible_posting_lines as (
select distinct s.source_disposition_id,pl.id as posting_line_id,pl.quantity as posting_line_quantity from source_identity s join identity_classification c on c.source_disposition_id=s.source_disposition_id and c.identity_consistent join public.vault_purchase_order_inventory_posting_lines pl on pl.receipt_allocation_id=s.receipt_allocation_id and pl.shopify_variant_id_snapshot=s.shopify_variant_id and pl.shopify_inventory_item_id_snapshot=s.shopify_inventory_item_id join public.vault_purchase_order_inventory_postings p on p.id=pl.posting_id and p.receipt_id=s.receipt_id and p.shopify_location_id_snapshot=s.shopify_location_id where exists(select 1 from public.vault_purchase_order_inventory_posting_events e where e.posting_id=p.id and e.event_type='shopify_succeeded')
),eligible_quantities as (
select s.source_disposition_id,coalesce(sum(epl.posting_line_quantity),0)::bigint as successful_posted_eligible_quantity from source_identity s left join eligible_posting_lines epl on epl.source_disposition_id=s.source_disposition_id group by s.source_disposition_id
),admitted_lots as (
select l.receipt_cost_disposition_id as source_disposition_id,sum(l.admitted_quantity)::bigint as admitted_quantity,sum(l.admitted_gbp_minor_units)::bigint as admitted_gbp_minor_units from public.vault_governed_inventory_cost_lots l group by l.receipt_cost_disposition_id
)
select s.purchase_order_id,s.purchase_order_line_id,s.size_allocation_id as purchase_order_line_size_allocation_id,s.receipt_id,s.receipt_allocation_id,s.source_disposition_id as receipt_cost_disposition_id,s.source_sellable_quantity,s.source_sellable_gbp_minor_units,e.successful_posted_eligible_quantity,coalesce(l.admitted_quantity,0) as admitted_quantity,coalesce(l.admitted_gbp_minor_units,0) as admitted_gbp_minor_units,s.source_sellable_quantity-coalesce(l.admitted_quantity,0) as unresolved_quantity,s.source_sellable_gbp_minor_units-coalesce(l.admitted_gbp_minor_units,0) as unresolved_gbp_minor_units,c.identity_consistent,(coalesce(l.admitted_quantity,0)<=e.successful_posted_eligible_quantity and coalesce(l.admitted_quantity,0)<=s.source_sellable_quantity and e.successful_posted_eligible_quantity<=s.source_sellable_quantity) as quantity_conservation_valid,coalesce(l.admitted_gbp_minor_units,0)<=s.source_sellable_gbp_minor_units as monetary_conservation_valid,case when not c.identity_consistent or e.successful_posted_eligible_quantity>s.source_sellable_quantity or coalesce(l.admitted_quantity,0)>e.successful_posted_eligible_quantity or coalesce(l.admitted_quantity,0)>s.source_sellable_quantity or coalesce(l.admitted_gbp_minor_units,0)>s.source_sellable_gbp_minor_units then 'UNAVAILABLE_INCONSISTENT_EVIDENCE' when e.successful_posted_eligible_quantity=0 then 'AWAITING_SHOPIFY_POSTING' when e.successful_posted_eligible_quantity>coalesce(l.admitted_quantity,0) then 'READY_FOR_ADMISSION' when coalesce(l.admitted_quantity,0)=s.source_sellable_quantity and coalesce(l.admitted_gbp_minor_units,0)=s.source_sellable_gbp_minor_units then 'COMPLETE' else 'PARTIAL' end as readiness_status,case when not c.identity_consistent then 'SHOPIFY_IDENTITY_MISMATCH' when e.successful_posted_eligible_quantity=0 then 'NO_SUCCESSFUL_POSTING' when e.successful_posted_eligible_quantity>coalesce(l.admitted_quantity,0) then 'SUCCESSFUL_POSTING_UNADMITTED' when coalesce(l.admitted_quantity,0)=s.source_sellable_quantity then 'COMPLETE' else 'PARTIAL' end as reason_code,case when not c.identity_consistent or e.successful_posted_eligible_quantity>s.source_sellable_quantity or coalesce(l.admitted_quantity,0)>e.successful_posted_eligible_quantity or coalesce(l.admitted_gbp_minor_units,0)>s.source_sellable_gbp_minor_units then 'CONSERVATION_UNAVAILABLE_OR_INCONSISTENT' else 'CONSERVATION_OK' end as conservation_status from source_identity s join identity_classification c on c.source_disposition_id=s.source_disposition_id join eligible_quantities e on e.source_disposition_id=s.source_disposition_id left join admitted_lots l on l.source_disposition_id=s.source_disposition_id;
revoke all on public.vault_governed_inventory_cost_state from public,anon,authenticated;grant select on public.vault_governed_inventory_cost_state to service_role;notify pgrst,'reload schema';
